import path from "node:path";
import { migrate } from "drizzle-orm/node-postgres/migrator";
import type { createDb } from "./client.js";

/** SQL migrations generated by `pnpm db:generate`, shipped with the package. */
export const migrationsFolder = path.join(import.meta.dirname, "../drizzle");

export async function runMigrations(db: ReturnType<typeof createDb>["db"]) {
  await migrate(db, { migrationsFolder });
}
